-- 0046_update_aws_labs_accented.sql
-- Cập nhật tiêu đề và mô tả (scenario) của 8 bài lab AWS sang tiếng Việt có dấu chuẩn,
-- áp dụng trực tiếp cho các database đã chạy migration 0045 trước đó (vốn mang text không dấu).

-- 1. Xóa các bản ghi không dấu nếu bản ghi có dấu đã vô tình tồn tại song song (tránh duplicate)
DELETE FROM cards
WHERE deck_id = (SELECT d.id FROM decks d JOIN subjects s ON d.subject_id = s.id WHERE s.slug = 'aws' AND d.slug = 'labs')
  AND front IN (
    'Lab AWS-2 - EC2 khong Public IP + SSM Session Manager',
    'Lab AWS-4 - Chay Docker trong EC2 (ECR + docker run)',
    'Lab AWS-6 - MSK (Managed Kafka): tao cluster, topic, producer/consumer',
    'Lab AWS-7 - Cloudflare truoc origin AWS',
    'Lab AWS-8 - Ra soat kien truc theo PCI-DSS & SOC 2'
  )
  AND EXISTS (
    SELECT 1 FROM cards c2
    WHERE c2.deck_id = cards.deck_id
      AND c2.front = CASE cards.front
        WHEN 'Lab AWS-2 - EC2 khong Public IP + SSM Session Manager' THEN 'Lab AWS-2 - EC2 không Public IP + SSM Session Manager'
        WHEN 'Lab AWS-4 - Chay Docker trong EC2 (ECR + docker run)' THEN 'Lab AWS-4 - Chạy Docker trong EC2 (ECR + docker run)'
        WHEN 'Lab AWS-6 - MSK (Managed Kafka): tao cluster, topic, producer/consumer' THEN 'Lab AWS-6 - MSK (Managed Kafka): tạo cluster, topic, producer/consumer'
        WHEN 'Lab AWS-7 - Cloudflare truoc origin AWS' THEN 'Lab AWS-7 - Cloudflare trước origin AWS'
        WHEN 'Lab AWS-8 - Ra soat kien truc theo PCI-DSS & SOC 2' THEN 'Lab AWS-8 - Rà soát kiến trúc theo PCI-DSS & SOC 2'
      END
  );

-- 2. Cập nhật tiêu đề front và toàn bộ payload (scenario tiếng Việt có dấu, steps, reference) cho 8 bài lab AWS
UPDATE cards AS c
SET front = v.target_front,
    payload = v.payload::jsonb,
    updated_at = NOW()
FROM (VALUES
  ('Lab AWS-1%', 'Lab AWS-1 - VPC: Internet Gateway, subnet, route table', '{"scenario": "VPC vpc-0abc123456789de01 (CIDR 10.0.0.0/16) đã được tạo sẵn. Bạn cần dựng đầy đủ hạ tầng mạng cần thiết để có 1 public subnet ra được internet.", "difficulty": "co_ban", "steps": [{"prompt": "Tạo mới 1 Internet Gateway.", "type": "command", "hint": "aws ec2 create-internet-gateway", "patterns": ["aws\\s+ec2\\s+create-internet-gateway"], "explanation": "create-internet-gateway tạo 1 IGW độc lập, chưa gắn vào VPC nào cả - phải attach ở bước sau."}, {"prompt": "Gắn Internet Gateway igw-0123456789abcdef0 vào VPC vpc-0abc123456789de01.", "type": "command", "hint": "aws ec2 attach-internet-gateway --vpc-id vpc-0abc123456789de01 --internet-gateway-id igw-0123456789abcdef0", "patterns": ["aws\\s+ec2\\s+attach-internet-gateway\\s+--vpc-id\\s+vpc-0abc123456789de01\\s+--internet-gateway-id\\s+igw-0123456789abcdef0", "aws\\s+ec2\\s+attach-internet-gateway\\s+--internet-gateway-id\\s+igw-0123456789abcdef0\\s+--vpc-id\\s+vpc-0abc123456789de01"], "explanation": "1 VPC chỉ attach được 1 IGW; phải attach-internet-gateway trước khi route table có thể trỏ tới nó."}, {"prompt": "Tạo 1 subnet mới trong VPC đó, CIDR 10.0.1.0/24 (sẽ dùng làm public subnet).", "type": "command", "hint": "aws ec2 create-subnet --vpc-id vpc-0abc123456789de01 --cidr-block 10.0.1.0/24", "patterns": ["aws\\s+ec2\\s+create-subnet\\s+--vpc-id\\s+vpc-0abc123456789de01\\s+--cidr-block\\s+10\\.0\\.1\\.0/24", "aws\\s+ec2\\s+create-subnet\\s+--cidr-block\\s+10\\.0\\.1\\.0/24\\s+--vpc-id\\s+vpc-0abc123456789de01"], "explanation": "create-subnet tạo subnet với 1 dải CIDR con nằm trong dải CIDR của VPC (10.0.0.0/16)."}, {"prompt": "Thêm route 0.0.0.0/0 trỏ về Internet Gateway igw-0123456789abcdef0 vào route table rtb-0a1b2c3d4e5f67890 (route table này sẽ gắn cho subnet public).", "type": "command", "hint": "aws ec2 create-route --route-table-id rtb-0a1b2c3d4e5f67890 --destination-cidr-block 0.0.0.0/0 --gateway-id igw-0123456789abcdef0", "patterns": ["aws\\s+ec2\\s+create-route\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890\\s+--destination-cidr-block\\s+0\\.0\\.0\\.0/0\\s+--gateway-id\\s+igw-0123456789abcdef0", "aws\\s+ec2\\s+create-route\\s+--destination-cidr-block\\s+0\\.0\\.0\\.0/0\\s+--gateway-id\\s+igw-0123456789abcdef0\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890"], "explanation": "Chính route này (0.0.0.0/0 -> igw) là thứ duy nhất biến 1 subnet thành ''public'' - không có gì khác về mặt cấu hình."}, {"prompt": "Gắn (associate) route table rtb-0a1b2c3d4e5f67890 vào subnet subnet-0fedcba9876543210 vừa tạo, để subnet này thực sự là public.", "type": "command", "hint": "aws ec2 associate-route-table --route-table-id rtb-0a1b2c3d4e5f67890 --subnet-id subnet-0fedcba9876543210", "patterns": ["aws\\s+ec2\\s+associate-route-table\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890\\s+--subnet-id\\s+subnet-0fedcba9876543210", "aws\\s+ec2\\s+associate-route-table\\s+--subnet-id\\s+subnet-0fedcba9876543210\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890"], "explanation": "Tạo route đúng chưa đủ - phải associate route table đó với đúng subnet mới có hiệu lực trên subnet ấy."}], "reference": "## VPC Networking: Internet Gateway, Subnet, Route Table\n\n**Trình tự chuẩn để có 1 public subnet:**\n1. `create-internet-gateway` (độc lập, chưa gắn VPC nào)\n2. `attach-internet-gateway --vpc-id ... --internet-gateway-id ...` (gắn IGW vào đúng 1 VPC)\n3. `create-subnet --vpc-id ... --cidr-block ...` (CIDR subnet phải nằm trong CIDR VPC)\n4. `create-route --route-table-id ... --destination-cidr-block 0.0.0.0/0 --gateway-id <igw-id>` (đây là điều KIỆN DUY NHẤT biến route table thành ''public'')\n5. `associate-route-table --route-table-id ... --subnet-id ...` (gắn route table đó vào đúng subnet)\n\n**Mental model:** subnet không tự nó ''public'' hay ''private'' - nó public/private hoàn toàn do route table của nó đang trỏ 0.0.0.0/0 về đâu (IGW = public, NAT Gateway = private có thể ra ngoài một chiều, không có route = isolated hoàn toàn)."}'::jsonb),
  ('Lab AWS-2%', 'Lab AWS-2 - EC2 không Public IP + SSM Session Manager', '{"scenario": "Cần launch 1 EC2 app server trong private subnet subnet-0a1b2c3d4e5f67890, không được có public IP, và phải truy cập được mà không mở port 22.", "difficulty": "trung_binh", "steps": [{"prompt": "Launch EC2 (AMI ami-0abcdef1234567890, loại t3.micro) vào subnet private đó, KHÔNG gán public IP, và đính kèm IAM instance profile tên SSMInstanceProfile (đã có policy AmazonSSMManagedInstanceCore).", "type": "command", "hint": "aws ec2 run-instances --image-id ami-0abcdef1234567890 --instance-type t3.micro --subnet-id subnet-0a1b2c3d4e5f67890 --no-associate-public-ip-address --iam-instance-profile Name=SSMInstanceProfile", "patterns": ["aws\\s+ec2\\s+run-instances(?=.*--image-id\\s+ami-0abcdef1234567890)(?=.*--instance-type\\s+t3\\.micro)(?=.*--subnet-id\\s+subnet-0a1b2c3d4e5f67890)(?=.*--no-associate-public-ip-address)(?=.*--iam-instance-profile\\s+Name=SSMInstanceProfile).*"], "explanation": "Không có --associate-public-ip-address (hoặc dùng --no-associate-public-ip-address) + không có Elastic IP = instance không có địa chỉ internet trực tiếp nào."}, {"prompt": "Kiểm tra xem SSM Agent của instance i-0123456789abcdef0 đã đăng ký ''online'' với SSM chưa.", "type": "command", "hint": "aws ssm describe-instance-information --filters Key=InstanceIds,Values=i-0123456789abcdef0", "patterns": ["aws\\s+ssm\\s+describe-instance-information\\s+--filters\\s+Key=InstanceIds,Values=i-0123456789abcdef0"], "output": "{\"InstanceInformationList\": [{\"InstanceId\": \"i-0123456789abcdef0\", \"PingStatus\": \"Online\", \"PlatformType\": \"Linux\"}]}", "explanation": "Instance phải online trên SSM (agent đã kết nối được ra ngoài qua HTTPS + có đúng IAM role) trước khi start-session hoạt động được."}, {"prompt": "Mở 1 session shell tương tác vào instance i-0123456789abcdef0 qua SSM (không cần SSH, không cần port 22).", "type": "command", "hint": "aws ssm start-session --target i-0123456789abcdef0", "patterns": ["aws\\s+ssm\\s+start-session\\s+--target\\s+i-0123456789abcdef0"], "explanation": "start-session mở 1 kênh shell qua SSM Agent - hoàn toàn không đi qua port 22 hay cần public IP."}, {"prompt": "Agent SSM trên EC2 cần IAM permission nào để đăng ký và hoạt động được (qua instance profile)?", "type": "choice", "choices": ["Managed policy AmazonSSMManagedInstanceCore gắn qua instance profile", "AdministratorAccess trên toàn account", "Không cần quyền IAM nào, chỉ cần mở port 22", "AmazonS3FullAccess"], "answer": 0, "explanation": "SSM Agent cần role gắn vào instance có chứa managed policy AmazonSSMManagedInstanceCore - policy này cấp vừng quyền tối thiểu để agent gọi về SSM service, không phải quyền admin toàn AWS."}], "reference": "## EC2 không Public IP + AWS Systems Manager Session Manager\n\n**Điều kiện để 1 EC2 không có public IP mà vẫn truy cập được an toàn:**\n1. Launch với `--no-associate-public-ip-address` (hoặc đơn giản là không gán Elastic IP, không auto-assign) trong private subnet.\n2. Gắn IAM instance profile có managed policy **AmazonSSMManagedInstanceCore** - đây là quyền tối thiểu để SSM Agent (có sẵn trên Amazon Linux 2/2023) kết nối ra ngoài qua HTTPS (outbound, không phải inbound).\n3. Kiểm tra instance đã ''Online'' với `describe-instance-information` trước khi `start-session`.\n4. `aws ssm start-session --target <instance-id>` mở shell - hoàn toàn không qua port 22, không cần bastion host, không cần VPN.\n\n**Mental model:** SSM đảo ngược hướng kết nối - thay vì ''ai đó từ ngoài SSH vào'', chính EC2 tự gọi RA NGOÀI (outbound HTTPS) tới SSM service, nên không cần mở bất kỳ port inbound nào."}'::jsonb),
  ('Lab AWS-3%', 'Lab AWS-3 - S3: bucket, block public access, versioning, encryption', '{"scenario": "Cần tạo 1 bucket S3 tên my-company-data-2026 để lưu dữ liệu nhạy cảm, phải đảm bảo không thể vô tình bị public và được mã hóa đúng chuẩn.", "difficulty": "co_ban", "steps": [{"prompt": "Tạo bucket S3 tên my-company-data-2026 trong region ap-southeast-1.", "type": "command", "hint": "aws s3 mb s3://my-company-data-2026 --region ap-southeast-1", "patterns": ["aws\\s+s3\\s+mb\\s+s3://my-company-data-2026\\s+--region\\s+ap-southeast-1"], "explanation": "s3 mb (make bucket) tạo bucket; tên bucket phải duy nhất toàn cầu trên toàn AWS, không chỉ trong account của bạn."}, {"prompt": "Chặn hoàn toàn mọi khả năng bucket này bị public (cả qua ACL và qua policy).", "type": "command", "hint": "aws s3api put-public-access-block --bucket my-company-data-2026 --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true", "patterns": ["aws\\s+s3api\\s+put-public-access-block\\s+--bucket\\s+my-company-data-2026\\s+--public-access-block-configuration\\s+BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true"], "explanation": "Cả 4 cờ đều phải true để chặn triệt để mọi đường khiến bucket/object vô tình thành public - thiếu 1 cờ vẫn còn kẻ hở."}, {"prompt": "Bật Versioning cho bucket, để chống ghi đè/xóa nhầm dữ liệu.", "type": "command", "hint": "aws s3api put-bucket-versioning --bucket my-company-data-2026 --versioning-configuration Status=Enabled", "patterns": ["aws\\s+s3api\\s+put-bucket-versioning\\s+--bucket\\s+my-company-data-2026\\s+--versioning-configuration\\s+Status=Enabled"], "explanation": "Khi đã Enabled, 1 lệnh delete chỉ tạo ''delete marker'', bản cũ của object vẫn còn truy xuất lại được."}, {"prompt": "Upload file report.pdf lên bucket, mã hóa SSE-KMS với key alias/my-key.", "type": "command", "hint": "aws s3 cp report.pdf s3://my-company-data-2026/report.pdf --sse aws:kms --sse-kms-key-id alias/my-key", "patterns": ["aws\\s+s3\\s+cp\\s+report\\.pdf\\s+s3://my-company-data-2026/report\\.pdf\\s+--sse\\s+aws:kms\\s+--sse-kms-key-id\\s+alias/my-key"], "explanation": "--sse aws:kms chọn SSE-KMS (thay vì SSE-S3 mặc định); --sse-kms-key-id chỉ định rõ key KMS nào được dùng, để việc truy cập key cũng audit được riêng."}, {"prompt": "Tạo 1 presigned URL cho object report.pdf, hết hạn sau 3600 giây (1 giờ), để 1 người ngoài download mà không cần credential AWS.", "type": "command", "hint": "aws s3 presign s3://my-company-data-2026/report.pdf --expires-in 3600", "patterns": ["aws\\s+s3\\s+presign\\s+s3://my-company-data-2026/report\\.pdf\\s+--expires-in\\s+3600"], "explanation": "presign tạo URL tạm có ký (signed) bằng chính credential của bạn nhưng không làm bucket public - URL chỉ dùng được cho ĐÚNG object đó, trong đúng thời hạn."}], "reference": "## S3: Bucket, Block Public Access, Versioning, SSE-KMS, Presigned URL\n\n**Thứ tự nên làm khi tạo 1 bucket chứa dữ liệu nhạy cảm:**\n1. `s3 mb s3://<tên-bucket>` - tên phải duy nhất toàn cầu.\n2. `s3api put-public-access-block` với CẢ 4 cờ `true` - đây là lớp chặn quan trọng nhất, ghi đè bất kỳ bucket policy/ACL nào có làm object public.\n3. `s3api put-bucket-versioning --versioning-configuration Status=Enabled` - chống xóa/ghi đè nhầm.\n4. Upload với `--sse aws:kms --sse-kms-key-id <alias>` (SSE-KMS) thay vì để mặc định SSE-S3, để việc truy cập key cũng được log/audit riêng - cần cho PCI/SOC 2.\n5. `s3 presign` khi cần chia sẻ 1 object cụ thể ra ngoài mà không public cả bucket và không cần cấp credential AWS cho người nhận."}'::jsonb),
  ('Lab AWS-4%', 'Lab AWS-4 - Chạy Docker trong EC2 (ECR + docker run)', '{"scenario": "EC2 Amazon Linux 2023 đã chạy sẵn, cần cài Docker và deploy 1 container từ image riêng tư lưu trong ECR (account 123456789012, region ap-southeast-1).", "difficulty": "trung_binh", "steps": [{"prompt": "Cài Docker engine trên Amazon Linux 2023.", "type": "command", "hint": "sudo dnf install -y docker", "patterns": ["sudo\\s+dnf\\s+install\\s+-y\\s+docker"], "explanation": "Amazon Linux 2023 dùng dnf (không phải yum/apt); -y để không phải xác nhận từng bước."}, {"prompt": "Bật (enable) và chạy ngay (start) Docker daemon, để nó tự khởi động lại khi EC2 reboot.", "type": "command", "hint": "sudo systemctl enable --now docker", "patterns": ["sudo\\s+systemctl\\s+enable\\s+--now\\s+docker"], "explanation": "--now vừa enable (tự chạy khi boot) vừa start ngay trong 1 lệnh, không cần gõ systemctl start riêng."}, {"prompt": "Đăng nhập vào ECR private registry của account 123456789012 tại region ap-southeast-1.", "type": "command", "hint": "aws ecr get-login-password --region ap-southeast-1 | docker login --username AWS --password-stdin 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com", "patterns": ["aws\\s+ecr\\s+get-login-password\\s+--region\\s+ap-southeast-1\\s*\\|\\s*docker\\s+login\\s+--username\\s+AWS\\s+--password-stdin\\s+123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com"], "explanation": "get-login-password trả về token tạm (hết hạn sau 12 giờ) chứ không phải mật khẩu cố định - pipe thẳng vào docker login, không lưu ra file."}, {"prompt": "Pull image app:latest từ registry ECR đó về EC2.", "type": "command", "hint": "docker pull 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/app:latest", "patterns": ["docker\\s+pull\\s+123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com/app:latest"], "explanation": "Tên image khi pull từ ECR luôn có dạng <account>.dkr.ecr.<region>.amazonaws.com/<repo>:<tag>."}, {"prompt": "Chạy container từ image đó: đặt tên ''webapp'', map port 8080 (host) vào 80 (container), và tự khởi động lại khi container crash/EC2 reboot.", "type": "command", "hint": "docker run -d --name webapp -p 8080:80 --restart unless-stopped 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/app:latest", "patterns": ["docker\\s+run\\s+(?=.*-d)(?=.*--name\\s+webapp)(?=.*-p\\s+8080:80)(?=.*--restart\\s+unless-stopped)(?=.*123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com/app:latest).*"], "explanation": "--restart unless-stopped là lựa chọn phổ biến trên EC2 production: tự chạy lại khi crash hoặc EC2 reboot, nhưng không chạy lại nếu bạn tự tay stop nó."}], "reference": "## Chạy Docker trong EC2: cài đặt + ECR + docker run\n\n**Thứ tự chuẩn:**\n1. Cài Docker (tên package/cách cài khác theo AMI: Amazon Linux 2023 dùng `dnf install docker`; Ubuntu dùng `apt install docker.io` hoặc Docker''s official repo).\n2. `systemctl enable --now docker` để daemon tự chạy lại sau reboot.\n3. Với image riêng tư trong ECR: phải `get-login-password` (token 12h) rồi pipe vào `docker login` - không có bước này sẽ bị ''no basic auth credentials'' khi pull.\n4. `docker pull <account>.dkr.ecr.<region>.amazonaws.com/<repo>:<tag>`.\n5. `docker run -d --name <tên> -p <host>:<container> --restart unless-stopped <image>` - bỏ --restart là quên 1 thứ rất dễ gây ''container biến mất sau khi EC2 reboot'' trong thực chiến.\n\n**Lưu ý IAM:** EC2 cần IAM role (instance profile) có quyền kéo image từ ECR (vd AmazonEC2ContainerRegistryReadOnly) - không nên tạo IAM user/access key riêng chỉ để pull image."}'::jsonb),
  ('Lab AWS-5%', 'Lab AWS-5 - ElastiCache Redis trong VPC', '{"scenario": "App cần 1 Redis cache, chỉ được truy cập từ trong VPC (private subnet subnet-0aaaaaaaaaaaaaaaa và subnet-0bbbbbbbbbbbbbbbb), security group của app là sg-0dddddddddddddddd.", "difficulty": "trung_binh", "steps": [{"prompt": "Tạo 1 cache subnet group tên app-cache-subnets, dùng 2 private subnet đã cho.", "type": "command", "hint": "aws elasticache create-cache-subnet-group --cache-subnet-group-name app-cache-subnets --cache-subnet-group-description \"App cache subnets\" --subnet-ids subnet-0aaaaaaaaaaaaaaaa subnet-0bbbbbbbbbbbbbbbb", "patterns": ["aws\\s+elasticache\\s+create-cache-subnet-group(?=.*--cache-subnet-group-name\\s+app-cache-subnets)(?=.*subnet-0aaaaaaaaaaaaaaaa)(?=.*subnet-0bbbbbbbbbbbbbbbb).*"], "explanation": "ElastiCache luôn chạy trong 1 subnet group (tập hợp subnet) - đảm bảo nó được đặt trong private subnet, không hề có tùy chọn để nó public."}, {"prompt": "Tạo Redis cluster tên app-cache, node type cache.t3.micro, 1 node, dùng subnet group vừa tạo và security group sg-0cccccccccccccccc (sẽ gắn rule mở cổng ở bước sau).", "type": "command", "hint": "aws elasticache create-cache-cluster --cache-cluster-id app-cache --engine redis --cache-node-type cache.t3.micro --num-cache-nodes 1 --cache-subnet-group-name app-cache-subnets --security-group-ids sg-0cccccccccccccccc", "patterns": ["aws\\s+elasticache\\s+create-cache-cluster(?=.*--cache-cluster-id\\s+app-cache)(?=.*--engine\\s+redis)(?=.*--cache-subnet-group-name\\s+app-cache-subnets)(?=.*sg-0cccccccccccccccc).*"], "explanation": "--engine redis chọn Redis (không phải memcached); security-group-ids là security group gắn vào cache, khác với security group của app gọi tới nó."}, {"prompt": "Mở cổng 6379 trên security group của cache (sg-0cccccccccccccccc), CHỈ cho phép từ security group của app (sg-0dddddddddddddddd) - không mở cho 0.0.0.0/0.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0cccccccccccccccc --protocol tcp --port 6379 --source-group sg-0dddddddddddddddd", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0cccccccccccccccc)(?=.*--port\\s+6379)(?=.*--source-group\\s+sg-0dddddddddddddddd).*"], "explanation": "--source-group (thay vì --cidr) giới hạn nguồn được phép chỉ là các instance mang security group đó - chính xác hơn và an toàn hơn rất nhiều so với mở theo dải IP."}, {"prompt": "Từ EC2 trong app, kết nối thử tới Redis endpoint app-cache.xxxxx.cache.amazonaws.com cổng 6379 bằng redis-cli.", "type": "command", "hint": "redis-cli -h app-cache.xxxxx.cache.amazonaws.com -p 6379", "patterns": ["redis-cli\\s+-h\\s+app-cache\\.xxxxx\\.cache\\.amazonaws\\.com\\s+-p\\s+6379"], "explanation": "-h chỉ host (endpoint của cache), -p chỉ port - redis-cli chỉ kết nối thành công nếu EC2 nằm trong (hoặc có route tới) VPC đó và security group cho phép."}], "reference": "## ElastiCache Redis: subnet group, security group, kết nối\n\n**Thứ tự chuẩn:**\n1. `create-cache-subnet-group` - khai báo cache sẽ nằm trong những subnet nào (luôn là private subnet trong thực tế).\n2. `create-cache-cluster --engine redis ...` gắn với subnet group + security group.\n3. Mở cổng cache (Redis 6379 / Memcached 11211) trên security group của cache, dùng `--source-group <sg-của-app>` - KHÔNG BAO GIỜ `--cidr 0.0.0.0/0`.\n4. Kết nối từ app bằng `redis-cli -h <endpoint> -p 6379` hoặc thư viện client (ioredis, redis-py...).\n\n**Mental model:** ElastiCache không có ''ở public/private'' như EC2 - nó mặc định KHÔNG BAO GIỜ có endpoint công khai, chỉ có thể gọi được từ trong (hoặc kết nối tới) chính VPC đó, nên ''bảo mật theo mạng'' (network-level) là lớp phòng thủ đầu tiên, security group là lớp thứ hai."}'::jsonb),
  ('Lab AWS-6%', 'Lab AWS-6 - MSK (Managed Kafka): tạo cluster, topic, producer/consumer', '{"scenario": "Hệ thống cần 1 Kafka topic ''orders'' để các service bán hàng gửi/đọc sự kiện đơn hàng, chạy trên AWS MSK.", "difficulty": "nang_cao", "steps": [{"prompt": "Tạo MSK cluster tên orders-cluster, kafka version 3.5.1, 3 broker node, cấu hình broker lấy từ file broker-info.json (chứa subnet + security group).", "type": "command", "hint": "aws kafka create-cluster --cluster-name orders-cluster --kafka-version 3.5.1 --number-of-broker-nodes 3 --broker-node-group-info file://broker-info.json", "patterns": ["aws\\s+kafka\\s+create-cluster(?=.*--cluster-name\\s+orders-cluster)(?=.*--kafka-version\\s+3\\.5\\.1)(?=.*--number-of-broker-nodes\\s+3)(?=.*--broker-node-group-info\\s+file://broker-info\\.json).*"], "explanation": "broker-node-group-info (file JSON riêng) là nơi khai báo subnet + security group cho các broker - giống ElastiCache, MSK cũng chỉ sống trong VPC, không có tùy chọn public."}, {"prompt": "Lấy địa chỉ bootstrap brokers của cluster có ARN arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234, để client biết kết nối vào đâu.", "type": "command", "hint": "aws kafka get-bootstrap-brokers --cluster-arn arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234", "patterns": ["aws\\s+kafka\\s+get-bootstrap-brokers\\s+--cluster-arn\\s+arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234"], "explanation": "Khác với Kafka tự quản lý (chỉ cần biết IP broker), với MSK bạn phải gọi API này để lấy đúng địa chỉ bootstrap - địa chỉ này có thể thay đổi khi AWS patch/scale cluster."}, {"prompt": "Tạo topic ''orders'' với 6 partition, replication factor 3, trên broker b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092.", "type": "command", "hint": "kafka-topics.sh --create --topic orders --partitions 6 --replication-factor 3 --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-topics\\.sh\\s+--create(?=.*--topic\\s+orders)(?=.*--partitions\\s+6)(?=.*--replication-factor\\s+3)(?=.*--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092).*"], "explanation": "6 partition cho phép tối đa 6 consumer trong cùng 1 group đọc song song; replication-factor 3 nghĩa là mỗi partition được sao lưu trên 3 broker khác nhau để chịu lỗi."}, {"prompt": "Gửi thử 1 message test vào topic orders qua console producer.", "type": "command", "hint": "kafka-console-producer.sh --topic orders --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-console-producer\\.sh\\s+--topic\\s+orders\\s+--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092"], "explanation": "console-producer mở 1 prompt nhập từng dòng, mỗi dòng Enter sẽ gửi 1 message vào topic - dùng để test nhanh, không dùng trong production code."}, {"prompt": "Đọc lại toàn bộ message trong topic orders từ đầu (từ message đầu tiên, không chỉ message mới).", "type": "command", "hint": "kafka-console-consumer.sh --topic orders --from-beginning --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-console-consumer\\.sh(?=.*--topic\\s+orders)(?=.*--from-beginning)(?=.*--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092).*"], "explanation": "--from-beginning đọc lại từ offset 0; bỏ cờ này thì consumer chỉ nhận message MỚI gửi kể từ lúc nó kết nối, bỏ qua hết lịch sử cũ."}], "reference": "## AWS MSK (Managed Kafka): tạo cluster, topic, producer/consumer\n\n**Khác biệt với tự dựng Kafka:** AWS vận hành broker (patch, scale, hạ tầng) nhưng bạn vẫn làm việc với đúng khái niệm Kafka gốc.\n\n**Thứ tự chuẩn:**\n1. `aws kafka create-cluster --broker-node-group-info file://...json` - subnet + security group khai báo trong file JSON, cluster luôn nằm trong VPC, không có endpoint public.\n2. `aws kafka get-bootstrap-brokers --cluster-arn ...` - lấy đúng địa chỉ broker hiện tại (có thể đổi khi AWS scale/patch).\n3. `kafka-topics.sh --create --topic <tên> --partitions <n> --replication-factor <r>` - partitions quyết định độ song song đọc; replication-factor quyết định độ chịu lỗi.\n4. `kafka-console-producer.sh` / `kafka-console-consumer.sh --from-beginning` chỉ để test nhanh từ dòng lệnh, không phải cách production gửi/nhận message (production dùng thư viện client: kafka-python, kafkajs...).\n\n**MSK IAM Authentication** là lựa chọn được khuyến nghị cho production: client dùng IAM role/credential có sẵn thay vì phải tự quản lý user/password SASL/SCRAM riêng."}'::jsonb),
  ('Lab AWS-7%', 'Lab AWS-7 - Cloudflare trước origin AWS', '{"scenario": "Website app.example.com đang chạy trên 1 ALB AWS, muốn đặt Cloudflare phía trước để có CDN/WAF và ẩn IP origin thực.", "difficulty": "trung_binh", "steps": [{"prompt": "DNS record cho app.example.com cần ở trạng thái nào để được Cloudflare WAF/CDN bảo vệ (không phải chỉ phân giải DNS)?", "type": "choice", "choices": ["Proxied (orange cloud)", "DNS only (grey cloud)", "Cả 2 trạng thái đều được bảo vệ giống nhau", "CNAME flattening"], "answer": 0, "explanation": "Chỉ có ''Proxied'' (orange cloud) mới khiến traffic đi QUA Cloudflare - ''DNS only'' (grey cloud) khiến khách truy cập thẳng vào IP origin thực, bỏ qua hoàn toàn mọi lớp bảo vệ của Cloudflare."}, {"prompt": "Origin AWS (ALB) đã có chứng chỉ SSL hợp lệ (vd AWS Certificate Manager). SSL/TLS mode nào trên Cloudflare là đúng chuẩn trong trường hợp này?", "type": "choice", "choices": ["Full (strict)", "Flexible", "Off", "Full (không strict)"], "answer": 0, "explanation": "Full (strict) mã hóa CẢ 2 đoạn (khách↔Cloudflare VÀ Cloudflare↔origin) VÀ kiểm tra chứng chỉ origin có hợp lệ không - đây là cấu hình đúng khi origin đã có cert thực sự, không phải Flexible (bỏ qua mã hóa đoạn Cloudflare↔origin)."}, {"prompt": "Giới hạn security group sg-0eeeeeeeeeeeeeeee của ALB chỉ nhận port 443 từ 1 dải IP của Cloudflare (ví dụ 173.245.48.0/20), thay vì mở cho mọi nơi.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 443 --cidr 173.245.48.0/20", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+443)(?=.*--cidr\\s+173\\.245\\.48\\.0/20).*"], "explanation": "Đây mới là 1 trong nhiều dải IP Cloudflare công bố (xem https://www.cloudflare.com/ips/) - thực tế phải allowlist ĐỦ toàn bộ danh sách, không chỉ 1 dải."}, {"prompt": "Thu hồi (revoke) rule inbound 443 cũ đang mở cho toàn bộ internet (0.0.0.0/0) trên cùng security group đó.", "type": "command", "hint": "aws ec2 revoke-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 443 --cidr 0.0.0.0/0", "patterns": ["aws\\s+ec2\\s+revoke-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+443)(?=.*--cidr\\s+0\\.0\\.0\\.0/0).*"], "explanation": "Nếu không revoke rule 0.0.0.0/0 cũ, ai đó vẫn có thể bỏ qua Cloudflare và gọi thẳng vào origin bằng IP thực - thêm rule Cloudflare mới là chưa đủ, phải xóa rule mở rộng cũ."}, {"prompt": "Nếu muốn KHÔNG mở bất kỳ port inbound nào trên AWS mà vẫn expose được app qua Cloudflare, nên dùng cơ chế nào?", "type": "choice", "choices": ["Cloudflare Tunnel (cloudflared)", "Mở thêm port 80 để dự phòng", "Dùng NAT Gateway", "Tạo thêm 1 Elastic IP"], "answer": 0, "explanation": "Cloudflare Tunnel (cloudflared) là 1 agent chỉ kết nối RA NGOÀI (outbound) tới Cloudflare - giống tinh thần của SSM với EC2 không public IP: không cần mở bất kỳ port inbound nào cả, kể cả port 443."}], "reference": "## Cloudflare đặt trước origin AWS\n\n**Thứ tự chuẩn để bảo vệ 1 origin AWS bằng Cloudflare:**\n1. DNS record phải **Proxied (orange cloud)** - ''DNS only'' (grey cloud) bỏ qua hoàn toàn Cloudflare.\n2. SSL/TLS mode **Full (strict)** khi origin đã có cert thực (ACM hoặc Cloudflare Origin CA) - Flexible để hở Cloudflare↔origin ở dạng plaintext.\n3. Giới hạn Security Group của origin CHỈ nhận traffic từ dải IP công bố của Cloudflare (`cloudflare.com/ips/`) rồi **revoke** rule 0.0.0.0/0 cũ - thiếu bước revoke là lỗ hổng phổ biến nhất.\n4. Nếu muốn không mở inbound port nào cả: dùng **Cloudflare Tunnel (cloudflared)**, 1 agent chỉ kết nối outbound, cùng tư tưởng với SSM Session Manager bên AWS."}'::jsonb),
  ('Lab AWS-8%', 'Lab AWS-8 - Rà soát kiến trúc theo PCI-DSS & SOC 2', '{"scenario": "Kiến trúc hiện tại: EC2 payment-service nằm trong PUBLIC subnet, security group mở 0.0.0.0/0 trên mọi port; bucket S3 payment-data-2026 chứa dữ liệu thẻ chưa mã hóa; IAM role gắn vào EC2 là AdministratorAccess; chưa có CloudTrail nào được tạo.", "difficulty": "nang_cao", "steps": [{"prompt": "Vấn đề PCI-DSS lớn nhất với việc EC2 payment-service đang nằm ở PUBLIC subnet là gì?", "type": "choice", "choices": ["Không cần thiết phải internet-facing; nên chuyển vào private subnet để giảm phạm vi CDE", "Vì EC2 luôn phải đặt ở public subnet", "Public subnet chạy nhanh hơn private subnet", "Không có vấn đề gì đáng kể"], "answer": 0, "explanation": "payment-service xử lý dữ liệu thẻ (thuộc CDE - Cardholder Data Environment) không cần thiết phải internet-facing trực tiếp - đặt nó trong private subnet (truy cập qua ALB/SSM) sẽ giảm trực tiếp phạm vi hệ thống bị audit PCI-DSS."}, {"prompt": "Tạo và bật 1 CloudTrail tên org-trail, lưu log vào bucket audit-logs-bucket-2026, để có bằng chứng audit trail cơ bản.", "type": "command", "hint": "aws cloudtrail create-trail --name org-trail --s3-bucket-name audit-logs-bucket-2026", "patterns": ["aws\\s+cloudtrail\\s+create-trail(?=.*--name\\s+org-trail)(?=.*--s3-bucket-name\\s+audit-logs-bucket-2026).*"], "explanation": "create-trail chỉ TẠO trail, chưa tự động ghi log - phải gọi thêm start-logging. Đây là bằng chứng cơ bản nhất cả PCI-DSS và SOC 2 đều đòi hỏi (accountability / audit trail)."}, {"prompt": "IAM role AdministratorAccess gắn trên EC2 payment-service vi phạm nguyên tắc nào mà auditor PCI-DSS/SOC 2 luôn kiểm tra đầu tiên?", "type": "choice", "choices": ["Least privilege (nguyên tắc quyền tối thiểu)", "Defense in depth", "Encryption at rest", "Không vi phạm nguyên tắc nào"], "answer": 0, "explanation": "Least privilege - một service chỉ cần đọc/viết vào 1 bucket và gọi vài API cụ thể lại được cấp toàn quyền trên toàn account là 1 finding kinh điển trong audit, vì 1 lần bị khai thác sẽ mất quyền kiểm soát toàn bộ AWS account."}, {"prompt": "Bật server-side encryption SSE-KMS mặc định trên bucket payment-data-2026, dùng key alias/pci-key.", "type": "command", "hint": "aws s3api put-bucket-encryption --bucket payment-data-2026 --server-side-encryption-configuration ''{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"aws:kms\",\"KMSMasterKeyID\":\"alias/pci-key\"}}]}''", "patterns": ["aws\\s+s3api\\s+put-bucket-encryption(?=.*--bucket\\s+payment-data-2026)(?=.*aws:kms)(?=.*alias/pci-key).*"], "explanation": "put-bucket-encryption đặt default encryption cho CẢ bucket - mọi object upload sau này tự động được mã hóa SSE-KMS dù người upload có chỉ định hay không, giảm rủi ro quên bật mã hóa cho 1 lần upload cụ thể."}, {"prompt": "Kiểm soát nào giúp PHÁT HIỆN ngay khi 1 security group bị mở 0.0.0.0/0 ngoài ý muốn trong tương lai (thay vì phải chờ đến lần audit sau mới biết)?", "type": "choice", "choices": ["AWS Config rule theo dõi cấu hình liên tục", "Chỉ kiểm tra thủ công mỗi 6 tháng", "Không cần vì đã fix 1 lần rồi", "Đổi Security Group sang dùng Network ACL"], "answer": 0, "explanation": "AWS Config có thể gắn 1 ''rule'' tự động kiểm tra cấu hình mỗi thay đổi và báo ngay khi có security group mở 0.0.0.0/0 - đây là ''continuous monitoring'' mà cả PCI-DSS và SOC 2 đều kỳ vọng, thay vì kiểm tra thủ công định kỳ."}], "reference": "## Rà soát kiến trúc AWS theo PCI-DSS & SOC 2\n\n**4 vấn đề kinh điển hay gặp và cách fix, theo thứ tự nên làm:**\n1. **Hệ thống xử lý dữ liệu thẻ nằm ở public subnet không cần thiết** -> chuyển vào private subnet, chỉ expose qua ALB/API Gateway - giảm trực tiếp phạm vi CDE (Cardholder Data Environment) phải audit.\n2. **Chưa có CloudTrail** -> `create-trail` + `start-logging` - bằng chứng audit trail cơ bản nhất mà auditor luôn hỏi đầu tiên.\n3. **IAM role quá rộng (AdministratorAccess) trên 1 service cụ thể** -> vi phạm least privilege - thu nhỏ lại chỉ còn đúng quyền service đó cần.\n4. **Dữ liệu nhạy cảm chưa mã hóa at-rest** -> `put-bucket-encryption` với SSE-KMS làm default cho cả bucket, không phụ thuộc người upload có nhớ chỉ định hay không.\n5. **Không có continuous monitoring** -> AWS Config rule + GuardDuty, để PHÁT HIỆN drift (vd security group bị mở lại) ngay lập tức thay vì chờ audit định kỳ mới biết."}'::jsonb)
) AS v(pattern, target_front, payload)
WHERE c.deck_id = (
    SELECT d.id
    FROM decks d
    JOIN subjects s ON d.subject_id = s.id
    WHERE s.slug = 'aws' AND d.slug = 'labs'
)
AND c.front LIKE v.pattern;

-- 3. Bổ sung nếu chưa tồn tại (cho trường hợp cài đặt mới hoặc thiếu card)
INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', v.target_front, v.payload, 'seed'
FROM (VALUES
  ('Lab AWS-1%', 'Lab AWS-1 - VPC: Internet Gateway, subnet, route table', '{"scenario": "VPC vpc-0abc123456789de01 (CIDR 10.0.0.0/16) đã được tạo sẵn. Bạn cần dựng đầy đủ hạ tầng mạng cần thiết để có 1 public subnet ra được internet.", "difficulty": "co_ban", "steps": [{"prompt": "Tạo mới 1 Internet Gateway.", "type": "command", "hint": "aws ec2 create-internet-gateway", "patterns": ["aws\\s+ec2\\s+create-internet-gateway"], "explanation": "create-internet-gateway tạo 1 IGW độc lập, chưa gắn vào VPC nào cả - phải attach ở bước sau."}, {"prompt": "Gắn Internet Gateway igw-0123456789abcdef0 vào VPC vpc-0abc123456789de01.", "type": "command", "hint": "aws ec2 attach-internet-gateway --vpc-id vpc-0abc123456789de01 --internet-gateway-id igw-0123456789abcdef0", "patterns": ["aws\\s+ec2\\s+attach-internet-gateway\\s+--vpc-id\\s+vpc-0abc123456789de01\\s+--internet-gateway-id\\s+igw-0123456789abcdef0", "aws\\s+ec2\\s+attach-internet-gateway\\s+--internet-gateway-id\\s+igw-0123456789abcdef0\\s+--vpc-id\\s+vpc-0abc123456789de01"], "explanation": "1 VPC chỉ attach được 1 IGW; phải attach-internet-gateway trước khi route table có thể trỏ tới nó."}, {"prompt": "Tạo 1 subnet mới trong VPC đó, CIDR 10.0.1.0/24 (sẽ dùng làm public subnet).", "type": "command", "hint": "aws ec2 create-subnet --vpc-id vpc-0abc123456789de01 --cidr-block 10.0.1.0/24", "patterns": ["aws\\s+ec2\\s+create-subnet\\s+--vpc-id\\s+vpc-0abc123456789de01\\s+--cidr-block\\s+10\\.0\\.1\\.0/24", "aws\\s+ec2\\s+create-subnet\\s+--cidr-block\\s+10\\.0\\.1\\.0/24\\s+--vpc-id\\s+vpc-0abc123456789de01"], "explanation": "create-subnet tạo subnet với 1 dải CIDR con nằm trong dải CIDR của VPC (10.0.0.0/16)."}, {"prompt": "Thêm route 0.0.0.0/0 trỏ về Internet Gateway igw-0123456789abcdef0 vào route table rtb-0a1b2c3d4e5f67890 (route table này sẽ gắn cho subnet public).", "type": "command", "hint": "aws ec2 create-route --route-table-id rtb-0a1b2c3d4e5f67890 --destination-cidr-block 0.0.0.0/0 --gateway-id igw-0123456789abcdef0", "patterns": ["aws\\s+ec2\\s+create-route\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890\\s+--destination-cidr-block\\s+0\\.0\\.0\\.0/0\\s+--gateway-id\\s+igw-0123456789abcdef0", "aws\\s+ec2\\s+create-route\\s+--destination-cidr-block\\s+0\\.0\\.0\\.0/0\\s+--gateway-id\\s+igw-0123456789abcdef0\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890"], "explanation": "Chính route này (0.0.0.0/0 -> igw) là thứ duy nhất biến 1 subnet thành ''public'' - không có gì khác về mặt cấu hình."}, {"prompt": "Gắn (associate) route table rtb-0a1b2c3d4e5f67890 vào subnet subnet-0fedcba9876543210 vừa tạo, để subnet này thực sự là public.", "type": "command", "hint": "aws ec2 associate-route-table --route-table-id rtb-0a1b2c3d4e5f67890 --subnet-id subnet-0fedcba9876543210", "patterns": ["aws\\s+ec2\\s+associate-route-table\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890\\s+--subnet-id\\s+subnet-0fedcba9876543210", "aws\\s+ec2\\s+associate-route-table\\s+--subnet-id\\s+subnet-0fedcba9876543210\\s+--route-table-id\\s+rtb-0a1b2c3d4e5f67890"], "explanation": "Tạo route đúng chưa đủ - phải associate route table đó với đúng subnet mới có hiệu lực trên subnet ấy."}], "reference": "## VPC Networking: Internet Gateway, Subnet, Route Table\n\n**Trình tự chuẩn để có 1 public subnet:**\n1. `create-internet-gateway` (độc lập, chưa gắn VPC nào)\n2. `attach-internet-gateway --vpc-id ... --internet-gateway-id ...` (gắn IGW vào đúng 1 VPC)\n3. `create-subnet --vpc-id ... --cidr-block ...` (CIDR subnet phải nằm trong CIDR VPC)\n4. `create-route --route-table-id ... --destination-cidr-block 0.0.0.0/0 --gateway-id <igw-id>` (đây là điều KIỆN DUY NHẤT biến route table thành ''public'')\n5. `associate-route-table --route-table-id ... --subnet-id ...` (gắn route table đó vào đúng subnet)\n\n**Mental model:** subnet không tự nó ''public'' hay ''private'' - nó public/private hoàn toàn do route table của nó đang trỏ 0.0.0.0/0 về đâu (IGW = public, NAT Gateway = private có thể ra ngoài một chiều, không có route = isolated hoàn toàn)."}'::jsonb),
  ('Lab AWS-2%', 'Lab AWS-2 - EC2 không Public IP + SSM Session Manager', '{"scenario": "Cần launch 1 EC2 app server trong private subnet subnet-0a1b2c3d4e5f67890, không được có public IP, và phải truy cập được mà không mở port 22.", "difficulty": "trung_binh", "steps": [{"prompt": "Launch EC2 (AMI ami-0abcdef1234567890, loại t3.micro) vào subnet private đó, KHÔNG gán public IP, và đính kèm IAM instance profile tên SSMInstanceProfile (đã có policy AmazonSSMManagedInstanceCore).", "type": "command", "hint": "aws ec2 run-instances --image-id ami-0abcdef1234567890 --instance-type t3.micro --subnet-id subnet-0a1b2c3d4e5f67890 --no-associate-public-ip-address --iam-instance-profile Name=SSMInstanceProfile", "patterns": ["aws\\s+ec2\\s+run-instances(?=.*--image-id\\s+ami-0abcdef1234567890)(?=.*--instance-type\\s+t3\\.micro)(?=.*--subnet-id\\s+subnet-0a1b2c3d4e5f67890)(?=.*--no-associate-public-ip-address)(?=.*--iam-instance-profile\\s+Name=SSMInstanceProfile).*"], "explanation": "Không có --associate-public-ip-address (hoặc dùng --no-associate-public-ip-address) + không có Elastic IP = instance không có địa chỉ internet trực tiếp nào."}, {"prompt": "Kiểm tra xem SSM Agent của instance i-0123456789abcdef0 đã đăng ký ''online'' với SSM chưa.", "type": "command", "hint": "aws ssm describe-instance-information --filters Key=InstanceIds,Values=i-0123456789abcdef0", "patterns": ["aws\\s+ssm\\s+describe-instance-information\\s+--filters\\s+Key=InstanceIds,Values=i-0123456789abcdef0"], "output": "{\"InstanceInformationList\": [{\"InstanceId\": \"i-0123456789abcdef0\", \"PingStatus\": \"Online\", \"PlatformType\": \"Linux\"}]}", "explanation": "Instance phải online trên SSM (agent đã kết nối được ra ngoài qua HTTPS + có đúng IAM role) trước khi start-session hoạt động được."}, {"prompt": "Mở 1 session shell tương tác vào instance i-0123456789abcdef0 qua SSM (không cần SSH, không cần port 22).", "type": "command", "hint": "aws ssm start-session --target i-0123456789abcdef0", "patterns": ["aws\\s+ssm\\s+start-session\\s+--target\\s+i-0123456789abcdef0"], "explanation": "start-session mở 1 kênh shell qua SSM Agent - hoàn toàn không đi qua port 22 hay cần public IP."}, {"prompt": "Agent SSM trên EC2 cần IAM permission nào để đăng ký và hoạt động được (qua instance profile)?", "type": "choice", "choices": ["Managed policy AmazonSSMManagedInstanceCore gắn qua instance profile", "AdministratorAccess trên toàn account", "Không cần quyền IAM nào, chỉ cần mở port 22", "AmazonS3FullAccess"], "answer": 0, "explanation": "SSM Agent cần role gắn vào instance có chứa managed policy AmazonSSMManagedInstanceCore - policy này cấp vừng quyền tối thiểu để agent gọi về SSM service, không phải quyền admin toàn AWS."}], "reference": "## EC2 không Public IP + AWS Systems Manager Session Manager\n\n**Điều kiện để 1 EC2 không có public IP mà vẫn truy cập được an toàn:**\n1. Launch với `--no-associate-public-ip-address` (hoặc đơn giản là không gán Elastic IP, không auto-assign) trong private subnet.\n2. Gắn IAM instance profile có managed policy **AmazonSSMManagedInstanceCore** - đây là quyền tối thiểu để SSM Agent (có sẵn trên Amazon Linux 2/2023) kết nối ra ngoài qua HTTPS (outbound, không phải inbound).\n3. Kiểm tra instance đã ''Online'' với `describe-instance-information` trước khi `start-session`.\n4. `aws ssm start-session --target <instance-id>` mở shell - hoàn toàn không qua port 22, không cần bastion host, không cần VPN.\n\n**Mental model:** SSM đảo ngược hướng kết nối - thay vì ''ai đó từ ngoài SSH vào'', chính EC2 tự gọi RA NGOÀI (outbound HTTPS) tới SSM service, nên không cần mở bất kỳ port inbound nào."}'::jsonb),
  ('Lab AWS-3%', 'Lab AWS-3 - S3: bucket, block public access, versioning, encryption', '{"scenario": "Cần tạo 1 bucket S3 tên my-company-data-2026 để lưu dữ liệu nhạy cảm, phải đảm bảo không thể vô tình bị public và được mã hóa đúng chuẩn.", "difficulty": "co_ban", "steps": [{"prompt": "Tạo bucket S3 tên my-company-data-2026 trong region ap-southeast-1.", "type": "command", "hint": "aws s3 mb s3://my-company-data-2026 --region ap-southeast-1", "patterns": ["aws\\s+s3\\s+mb\\s+s3://my-company-data-2026\\s+--region\\s+ap-southeast-1"], "explanation": "s3 mb (make bucket) tạo bucket; tên bucket phải duy nhất toàn cầu trên toàn AWS, không chỉ trong account của bạn."}, {"prompt": "Chặn hoàn toàn mọi khả năng bucket này bị public (cả qua ACL và qua policy).", "type": "command", "hint": "aws s3api put-public-access-block --bucket my-company-data-2026 --public-access-block-configuration BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true", "patterns": ["aws\\s+s3api\\s+put-public-access-block\\s+--bucket\\s+my-company-data-2026\\s+--public-access-block-configuration\\s+BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true"], "explanation": "Cả 4 cờ đều phải true để chặn triệt để mọi đường khiến bucket/object vô tình thành public - thiếu 1 cờ vẫn còn kẻ hở."}, {"prompt": "Bật Versioning cho bucket, để chống ghi đè/xóa nhầm dữ liệu.", "type": "command", "hint": "aws s3api put-bucket-versioning --bucket my-company-data-2026 --versioning-configuration Status=Enabled", "patterns": ["aws\\s+s3api\\s+put-bucket-versioning\\s+--bucket\\s+my-company-data-2026\\s+--versioning-configuration\\s+Status=Enabled"], "explanation": "Khi đã Enabled, 1 lệnh delete chỉ tạo ''delete marker'', bản cũ của object vẫn còn truy xuất lại được."}, {"prompt": "Upload file report.pdf lên bucket, mã hóa SSE-KMS với key alias/my-key.", "type": "command", "hint": "aws s3 cp report.pdf s3://my-company-data-2026/report.pdf --sse aws:kms --sse-kms-key-id alias/my-key", "patterns": ["aws\\s+s3\\s+cp\\s+report\\.pdf\\s+s3://my-company-data-2026/report\\.pdf\\s+--sse\\s+aws:kms\\s+--sse-kms-key-id\\s+alias/my-key"], "explanation": "--sse aws:kms chọn SSE-KMS (thay vì SSE-S3 mặc định); --sse-kms-key-id chỉ định rõ key KMS nào được dùng, để việc truy cập key cũng audit được riêng."}, {"prompt": "Tạo 1 presigned URL cho object report.pdf, hết hạn sau 3600 giây (1 giờ), để 1 người ngoài download mà không cần credential AWS.", "type": "command", "hint": "aws s3 presign s3://my-company-data-2026/report.pdf --expires-in 3600", "patterns": ["aws\\s+s3\\s+presign\\s+s3://my-company-data-2026/report\\.pdf\\s+--expires-in\\s+3600"], "explanation": "presign tạo URL tạm có ký (signed) bằng chính credential của bạn nhưng không làm bucket public - URL chỉ dùng được cho ĐÚNG object đó, trong đúng thời hạn."}], "reference": "## S3: Bucket, Block Public Access, Versioning, SSE-KMS, Presigned URL\n\n**Thứ tự nên làm khi tạo 1 bucket chứa dữ liệu nhạy cảm:**\n1. `s3 mb s3://<tên-bucket>` - tên phải duy nhất toàn cầu.\n2. `s3api put-public-access-block` với CẢ 4 cờ `true` - đây là lớp chặn quan trọng nhất, ghi đè bất kỳ bucket policy/ACL nào có làm object public.\n3. `s3api put-bucket-versioning --versioning-configuration Status=Enabled` - chống xóa/ghi đè nhầm.\n4. Upload với `--sse aws:kms --sse-kms-key-id <alias>` (SSE-KMS) thay vì để mặc định SSE-S3, để việc truy cập key cũng được log/audit riêng - cần cho PCI/SOC 2.\n5. `s3 presign` khi cần chia sẻ 1 object cụ thể ra ngoài mà không public cả bucket và không cần cấp credential AWS cho người nhận."}'::jsonb),
  ('Lab AWS-4%', 'Lab AWS-4 - Chạy Docker trong EC2 (ECR + docker run)', '{"scenario": "EC2 Amazon Linux 2023 đã chạy sẵn, cần cài Docker và deploy 1 container từ image riêng tư lưu trong ECR (account 123456789012, region ap-southeast-1).", "difficulty": "trung_binh", "steps": [{"prompt": "Cài Docker engine trên Amazon Linux 2023.", "type": "command", "hint": "sudo dnf install -y docker", "patterns": ["sudo\\s+dnf\\s+install\\s+-y\\s+docker"], "explanation": "Amazon Linux 2023 dùng dnf (không phải yum/apt); -y để không phải xác nhận từng bước."}, {"prompt": "Bật (enable) và chạy ngay (start) Docker daemon, để nó tự khởi động lại khi EC2 reboot.", "type": "command", "hint": "sudo systemctl enable --now docker", "patterns": ["sudo\\s+systemctl\\s+enable\\s+--now\\s+docker"], "explanation": "--now vừa enable (tự chạy khi boot) vừa start ngay trong 1 lệnh, không cần gõ systemctl start riêng."}, {"prompt": "Đăng nhập vào ECR private registry của account 123456789012 tại region ap-southeast-1.", "type": "command", "hint": "aws ecr get-login-password --region ap-southeast-1 | docker login --username AWS --password-stdin 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com", "patterns": ["aws\\s+ecr\\s+get-login-password\\s+--region\\s+ap-southeast-1\\s*\\|\\s*docker\\s+login\\s+--username\\s+AWS\\s+--password-stdin\\s+123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com"], "explanation": "get-login-password trả về token tạm (hết hạn sau 12 giờ) chứ không phải mật khẩu cố định - pipe thẳng vào docker login, không lưu ra file."}, {"prompt": "Pull image app:latest từ registry ECR đó về EC2.", "type": "command", "hint": "docker pull 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/app:latest", "patterns": ["docker\\s+pull\\s+123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com/app:latest"], "explanation": "Tên image khi pull từ ECR luôn có dạng <account>.dkr.ecr.<region>.amazonaws.com/<repo>:<tag>."}, {"prompt": "Chạy container từ image đó: đặt tên ''webapp'', map port 8080 (host) vào 80 (container), và tự khởi động lại khi container crash/EC2 reboot.", "type": "command", "hint": "docker run -d --name webapp -p 8080:80 --restart unless-stopped 123456789012.dkr.ecr.ap-southeast-1.amazonaws.com/app:latest", "patterns": ["docker\\s+run\\s+(?=.*-d)(?=.*--name\\s+webapp)(?=.*-p\\s+8080:80)(?=.*--restart\\s+unless-stopped)(?=.*123456789012\\.dkr\\.ecr\\.ap-southeast-1\\.amazonaws\\.com/app:latest).*"], "explanation": "--restart unless-stopped là lựa chọn phổ biến trên EC2 production: tự chạy lại khi crash hoặc EC2 reboot, nhưng không chạy lại nếu bạn tự tay stop nó."}], "reference": "## Chạy Docker trong EC2: cài đặt + ECR + docker run\n\n**Thứ tự chuẩn:**\n1. Cài Docker (tên package/cách cài khác theo AMI: Amazon Linux 2023 dùng `dnf install docker`; Ubuntu dùng `apt install docker.io` hoặc Docker''s official repo).\n2. `systemctl enable --now docker` để daemon tự chạy lại sau reboot.\n3. Với image riêng tư trong ECR: phải `get-login-password` (token 12h) rồi pipe vào `docker login` - không có bước này sẽ bị ''no basic auth credentials'' khi pull.\n4. `docker pull <account>.dkr.ecr.<region>.amazonaws.com/<repo>:<tag>`.\n5. `docker run -d --name <tên> -p <host>:<container> --restart unless-stopped <image>` - bỏ --restart là quên 1 thứ rất dễ gây ''container biến mất sau khi EC2 reboot'' trong thực chiến.\n\n**Lưu ý IAM:** EC2 cần IAM role (instance profile) có quyền kéo image từ ECR (vd AmazonEC2ContainerRegistryReadOnly) - không nên tạo IAM user/access key riêng chỉ để pull image."}'::jsonb),
  ('Lab AWS-5%', 'Lab AWS-5 - ElastiCache Redis trong VPC', '{"scenario": "App cần 1 Redis cache, chỉ được truy cập từ trong VPC (private subnet subnet-0aaaaaaaaaaaaaaaa và subnet-0bbbbbbbbbbbbbbbb), security group của app là sg-0dddddddddddddddd.", "difficulty": "trung_binh", "steps": [{"prompt": "Tạo 1 cache subnet group tên app-cache-subnets, dùng 2 private subnet đã cho.", "type": "command", "hint": "aws elasticache create-cache-subnet-group --cache-subnet-group-name app-cache-subnets --cache-subnet-group-description \"App cache subnets\" --subnet-ids subnet-0aaaaaaaaaaaaaaaa subnet-0bbbbbbbbbbbbbbbb", "patterns": ["aws\\s+elasticache\\s+create-cache-subnet-group(?=.*--cache-subnet-group-name\\s+app-cache-subnets)(?=.*subnet-0aaaaaaaaaaaaaaaa)(?=.*subnet-0bbbbbbbbbbbbbbbb).*"], "explanation": "ElastiCache luôn chạy trong 1 subnet group (tập hợp subnet) - đảm bảo nó được đặt trong private subnet, không hề có tùy chọn để nó public."}, {"prompt": "Tạo Redis cluster tên app-cache, node type cache.t3.micro, 1 node, dùng subnet group vừa tạo và security group sg-0cccccccccccccccc (sẽ gắn rule mở cổng ở bước sau).", "type": "command", "hint": "aws elasticache create-cache-cluster --cache-cluster-id app-cache --engine redis --cache-node-type cache.t3.micro --num-cache-nodes 1 --cache-subnet-group-name app-cache-subnets --security-group-ids sg-0cccccccccccccccc", "patterns": ["aws\\s+elasticache\\s+create-cache-cluster(?=.*--cache-cluster-id\\s+app-cache)(?=.*--engine\\s+redis)(?=.*--cache-subnet-group-name\\s+app-cache-subnets)(?=.*sg-0cccccccccccccccc).*"], "explanation": "--engine redis chọn Redis (không phải memcached); security-group-ids là security group gắn vào cache, khác với security group của app gọi tới nó."}, {"prompt": "Mở cổng 6379 trên security group của cache (sg-0cccccccccccccccc), CHỈ cho phép từ security group của app (sg-0dddddddddddddddd) - không mở cho 0.0.0.0/0.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0cccccccccccccccc --protocol tcp --port 6379 --source-group sg-0dddddddddddddddd", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0cccccccccccccccc)(?=.*--port\\s+6379)(?=.*--source-group\\s+sg-0dddddddddddddddd).*"], "explanation": "--source-group (thay vì --cidr) giới hạn nguồn được phép chỉ là các instance mang security group đó - chính xác hơn và an toàn hơn rất nhiều so với mở theo dải IP."}, {"prompt": "Từ EC2 trong app, kết nối thử tới Redis endpoint app-cache.xxxxx.cache.amazonaws.com cổng 6379 bằng redis-cli.", "type": "command", "hint": "redis-cli -h app-cache.xxxxx.cache.amazonaws.com -p 6379", "patterns": ["redis-cli\\s+-h\\s+app-cache\\.xxxxx\\.cache\\.amazonaws\\.com\\s+-p\\s+6379"], "explanation": "-h chỉ host (endpoint của cache), -p chỉ port - redis-cli chỉ kết nối thành công nếu EC2 nằm trong (hoặc có route tới) VPC đó và security group cho phép."}], "reference": "## ElastiCache Redis: subnet group, security group, kết nối\n\n**Thứ tự chuẩn:**\n1. `create-cache-subnet-group` - khai báo cache sẽ nằm trong những subnet nào (luôn là private subnet trong thực tế).\n2. `create-cache-cluster --engine redis ...` gắn với subnet group + security group.\n3. Mở cổng cache (Redis 6379 / Memcached 11211) trên security group của cache, dùng `--source-group <sg-của-app>` - KHÔNG BAO GIỜ `--cidr 0.0.0.0/0`.\n4. Kết nối từ app bằng `redis-cli -h <endpoint> -p 6379` hoặc thư viện client (ioredis, redis-py...).\n\n**Mental model:** ElastiCache không có ''ở public/private'' như EC2 - nó mặc định KHÔNG BAO GIỜ có endpoint công khai, chỉ có thể gọi được từ trong (hoặc kết nối tới) chính VPC đó, nên ''bảo mật theo mạng'' (network-level) là lớp phòng thủ đầu tiên, security group là lớp thứ hai."}'::jsonb),
  ('Lab AWS-6%', 'Lab AWS-6 - MSK (Managed Kafka): tạo cluster, topic, producer/consumer', '{"scenario": "Hệ thống cần 1 Kafka topic ''orders'' để các service bán hàng gửi/đọc sự kiện đơn hàng, chạy trên AWS MSK.", "difficulty": "nang_cao", "steps": [{"prompt": "Tạo MSK cluster tên orders-cluster, kafka version 3.5.1, 3 broker node, cấu hình broker lấy từ file broker-info.json (chứa subnet + security group).", "type": "command", "hint": "aws kafka create-cluster --cluster-name orders-cluster --kafka-version 3.5.1 --number-of-broker-nodes 3 --broker-node-group-info file://broker-info.json", "patterns": ["aws\\s+kafka\\s+create-cluster(?=.*--cluster-name\\s+orders-cluster)(?=.*--kafka-version\\s+3\\.5\\.1)(?=.*--number-of-broker-nodes\\s+3)(?=.*--broker-node-group-info\\s+file://broker-info\\.json).*"], "explanation": "broker-node-group-info (file JSON riêng) là nơi khai báo subnet + security group cho các broker - giống ElastiCache, MSK cũng chỉ sống trong VPC, không có tùy chọn public."}, {"prompt": "Lấy địa chỉ bootstrap brokers của cluster có ARN arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234, để client biết kết nối vào đâu.", "type": "command", "hint": "aws kafka get-bootstrap-brokers --cluster-arn arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234", "patterns": ["aws\\s+kafka\\s+get-bootstrap-brokers\\s+--cluster-arn\\s+arn:aws:kafka:ap-southeast-1:123456789012:cluster/orders-cluster/abcd1234"], "explanation": "Khác với Kafka tự quản lý (chỉ cần biết IP broker), với MSK bạn phải gọi API này để lấy đúng địa chỉ bootstrap - địa chỉ này có thể thay đổi khi AWS patch/scale cluster."}, {"prompt": "Tạo topic ''orders'' với 6 partition, replication factor 3, trên broker b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092.", "type": "command", "hint": "kafka-topics.sh --create --topic orders --partitions 6 --replication-factor 3 --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-topics\\.sh\\s+--create(?=.*--topic\\s+orders)(?=.*--partitions\\s+6)(?=.*--replication-factor\\s+3)(?=.*--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092).*"], "explanation": "6 partition cho phép tối đa 6 consumer trong cùng 1 group đọc song song; replication-factor 3 nghĩa là mỗi partition được sao lưu trên 3 broker khác nhau để chịu lỗi."}, {"prompt": "Gửi thử 1 message test vào topic orders qua console producer.", "type": "command", "hint": "kafka-console-producer.sh --topic orders --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-console-producer\\.sh\\s+--topic\\s+orders\\s+--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092"], "explanation": "console-producer mở 1 prompt nhập từng dòng, mỗi dòng Enter sẽ gửi 1 message vào topic - dùng để test nhanh, không dùng trong production code."}, {"prompt": "Đọc lại toàn bộ message trong topic orders từ đầu (từ message đầu tiên, không chỉ message mới).", "type": "command", "hint": "kafka-console-consumer.sh --topic orders --from-beginning --bootstrap-server b-1.orders-cluster.xxxx.kafka.ap-southeast-1.amazonaws.com:9092", "patterns": ["kafka-console-consumer\\.sh(?=.*--topic\\s+orders)(?=.*--from-beginning)(?=.*--bootstrap-server\\s+b-1\\.orders-cluster\\.xxxx\\.kafka\\.ap-southeast-1\\.amazonaws\\.com:9092).*"], "explanation": "--from-beginning đọc lại từ offset 0; bỏ cờ này thì consumer chỉ nhận message MỚI gửi kể từ lúc nó kết nối, bỏ qua hết lịch sử cũ."}], "reference": "## AWS MSK (Managed Kafka): tạo cluster, topic, producer/consumer\n\n**Khác biệt với tự dựng Kafka:** AWS vận hành broker (patch, scale, hạ tầng) nhưng bạn vẫn làm việc với đúng khái niệm Kafka gốc.\n\n**Thứ tự chuẩn:**\n1. `aws kafka create-cluster --broker-node-group-info file://...json` - subnet + security group khai báo trong file JSON, cluster luôn nằm trong VPC, không có endpoint public.\n2. `aws kafka get-bootstrap-brokers --cluster-arn ...` - lấy đúng địa chỉ broker hiện tại (có thể đổi khi AWS scale/patch).\n3. `kafka-topics.sh --create --topic <tên> --partitions <n> --replication-factor <r>` - partitions quyết định độ song song đọc; replication-factor quyết định độ chịu lỗi.\n4. `kafka-console-producer.sh` / `kafka-console-consumer.sh --from-beginning` chỉ để test nhanh từ dòng lệnh, không phải cách production gửi/nhận message (production dùng thư viện client: kafka-python, kafkajs...).\n\n**MSK IAM Authentication** là lựa chọn được khuyến nghị cho production: client dùng IAM role/credential có sẵn thay vì phải tự quản lý user/password SASL/SCRAM riêng."}'::jsonb),
  ('Lab AWS-7%', 'Lab AWS-7 - Cloudflare trước origin AWS', '{"scenario": "Website app.example.com đang chạy trên 1 ALB AWS, muốn đặt Cloudflare phía trước để có CDN/WAF và ẩn IP origin thực.", "difficulty": "trung_binh", "steps": [{"prompt": "DNS record cho app.example.com cần ở trạng thái nào để được Cloudflare WAF/CDN bảo vệ (không phải chỉ phân giải DNS)?", "type": "choice", "choices": ["Proxied (orange cloud)", "DNS only (grey cloud)", "Cả 2 trạng thái đều được bảo vệ giống nhau", "CNAME flattening"], "answer": 0, "explanation": "Chỉ có ''Proxied'' (orange cloud) mới khiến traffic đi QUA Cloudflare - ''DNS only'' (grey cloud) khiến khách truy cập thẳng vào IP origin thực, bỏ qua hoàn toàn mọi lớp bảo vệ của Cloudflare."}, {"prompt": "Origin AWS (ALB) đã có chứng chỉ SSL hợp lệ (vd AWS Certificate Manager). SSL/TLS mode nào trên Cloudflare là đúng chuẩn trong trường hợp này?", "type": "choice", "choices": ["Full (strict)", "Flexible", "Off", "Full (không strict)"], "answer": 0, "explanation": "Full (strict) mã hóa CẢ 2 đoạn (khách↔Cloudflare VÀ Cloudflare↔origin) VÀ kiểm tra chứng chỉ origin có hợp lệ không - đây là cấu hình đúng khi origin đã có cert thực sự, không phải Flexible (bỏ qua mã hóa đoạn Cloudflare↔origin)."}, {"prompt": "Giới hạn security group sg-0eeeeeeeeeeeeeeee của ALB chỉ nhận port 443 từ 1 dải IP của Cloudflare (ví dụ 173.245.48.0/20), thay vì mở cho mọi nơi.", "type": "command", "hint": "aws ec2 authorize-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 443 --cidr 173.245.48.0/20", "patterns": ["aws\\s+ec2\\s+authorize-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+443)(?=.*--cidr\\s+173\\.245\\.48\\.0/20).*"], "explanation": "Đây mới là 1 trong nhiều dải IP Cloudflare công bố (xem https://www.cloudflare.com/ips/) - thực tế phải allowlist ĐỦ toàn bộ danh sách, không chỉ 1 dải."}, {"prompt": "Thu hồi (revoke) rule inbound 443 cũ đang mở cho toàn bộ internet (0.0.0.0/0) trên cùng security group đó.", "type": "command", "hint": "aws ec2 revoke-security-group-ingress --group-id sg-0eeeeeeeeeeeeeeee --protocol tcp --port 443 --cidr 0.0.0.0/0", "patterns": ["aws\\s+ec2\\s+revoke-security-group-ingress(?=.*--group-id\\s+sg-0eeeeeeeeeeeeeeee)(?=.*--port\\s+443)(?=.*--cidr\\s+0\\.0\\.0\\.0/0).*"], "explanation": "Nếu không revoke rule 0.0.0.0/0 cũ, ai đó vẫn có thể bỏ qua Cloudflare và gọi thẳng vào origin bằng IP thực - thêm rule Cloudflare mới là chưa đủ, phải xóa rule mở rộng cũ."}, {"prompt": "Nếu muốn KHÔNG mở bất kỳ port inbound nào trên AWS mà vẫn expose được app qua Cloudflare, nên dùng cơ chế nào?", "type": "choice", "choices": ["Cloudflare Tunnel (cloudflared)", "Mở thêm port 80 để dự phòng", "Dùng NAT Gateway", "Tạo thêm 1 Elastic IP"], "answer": 0, "explanation": "Cloudflare Tunnel (cloudflared) là 1 agent chỉ kết nối RA NGOÀI (outbound) tới Cloudflare - giống tinh thần của SSM với EC2 không public IP: không cần mở bất kỳ port inbound nào cả, kể cả port 443."}], "reference": "## Cloudflare đặt trước origin AWS\n\n**Thứ tự chuẩn để bảo vệ 1 origin AWS bằng Cloudflare:**\n1. DNS record phải **Proxied (orange cloud)** - ''DNS only'' (grey cloud) bỏ qua hoàn toàn Cloudflare.\n2. SSL/TLS mode **Full (strict)** khi origin đã có cert thực (ACM hoặc Cloudflare Origin CA) - Flexible để hở Cloudflare↔origin ở dạng plaintext.\n3. Giới hạn Security Group của origin CHỈ nhận traffic từ dải IP công bố của Cloudflare (`cloudflare.com/ips/`) rồi **revoke** rule 0.0.0.0/0 cũ - thiếu bước revoke là lỗ hổng phổ biến nhất.\n4. Nếu muốn không mở inbound port nào cả: dùng **Cloudflare Tunnel (cloudflared)**, 1 agent chỉ kết nối outbound, cùng tư tưởng với SSM Session Manager bên AWS."}'::jsonb),
  ('Lab AWS-8%', 'Lab AWS-8 - Rà soát kiến trúc theo PCI-DSS & SOC 2', '{"scenario": "Kiến trúc hiện tại: EC2 payment-service nằm trong PUBLIC subnet, security group mở 0.0.0.0/0 trên mọi port; bucket S3 payment-data-2026 chứa dữ liệu thẻ chưa mã hóa; IAM role gắn vào EC2 là AdministratorAccess; chưa có CloudTrail nào được tạo.", "difficulty": "nang_cao", "steps": [{"prompt": "Vấn đề PCI-DSS lớn nhất với việc EC2 payment-service đang nằm ở PUBLIC subnet là gì?", "type": "choice", "choices": ["Không cần thiết phải internet-facing; nên chuyển vào private subnet để giảm phạm vi CDE", "Vì EC2 luôn phải đặt ở public subnet", "Public subnet chạy nhanh hơn private subnet", "Không có vấn đề gì đáng kể"], "answer": 0, "explanation": "payment-service xử lý dữ liệu thẻ (thuộc CDE - Cardholder Data Environment) không cần thiết phải internet-facing trực tiếp - đặt nó trong private subnet (truy cập qua ALB/SSM) sẽ giảm trực tiếp phạm vi hệ thống bị audit PCI-DSS."}, {"prompt": "Tạo và bật 1 CloudTrail tên org-trail, lưu log vào bucket audit-logs-bucket-2026, để có bằng chứng audit trail cơ bản.", "type": "command", "hint": "aws cloudtrail create-trail --name org-trail --s3-bucket-name audit-logs-bucket-2026", "patterns": ["aws\\s+cloudtrail\\s+create-trail(?=.*--name\\s+org-trail)(?=.*--s3-bucket-name\\s+audit-logs-bucket-2026).*"], "explanation": "create-trail chỉ TẠO trail, chưa tự động ghi log - phải gọi thêm start-logging. Đây là bằng chứng cơ bản nhất cả PCI-DSS và SOC 2 đều đòi hỏi (accountability / audit trail)."}, {"prompt": "IAM role AdministratorAccess gắn trên EC2 payment-service vi phạm nguyên tắc nào mà auditor PCI-DSS/SOC 2 luôn kiểm tra đầu tiên?", "type": "choice", "choices": ["Least privilege (nguyên tắc quyền tối thiểu)", "Defense in depth", "Encryption at rest", "Không vi phạm nguyên tắc nào"], "answer": 0, "explanation": "Least privilege - một service chỉ cần đọc/viết vào 1 bucket và gọi vài API cụ thể lại được cấp toàn quyền trên toàn account là 1 finding kinh điển trong audit, vì 1 lần bị khai thác sẽ mất quyền kiểm soát toàn bộ AWS account."}, {"prompt": "Bật server-side encryption SSE-KMS mặc định trên bucket payment-data-2026, dùng key alias/pci-key.", "type": "command", "hint": "aws s3api put-bucket-encryption --bucket payment-data-2026 --server-side-encryption-configuration ''{\"Rules\":[{\"ApplyServerSideEncryptionByDefault\":{\"SSEAlgorithm\":\"aws:kms\",\"KMSMasterKeyID\":\"alias/pci-key\"}}]}''", "patterns": ["aws\\s+s3api\\s+put-bucket-encryption(?=.*--bucket\\s+payment-data-2026)(?=.*aws:kms)(?=.*alias/pci-key).*"], "explanation": "put-bucket-encryption đặt default encryption cho CẢ bucket - mọi object upload sau này tự động được mã hóa SSE-KMS dù người upload có chỉ định hay không, giảm rủi ro quên bật mã hóa cho 1 lần upload cụ thể."}, {"prompt": "Kiểm soát nào giúp PHÁT HIỆN ngay khi 1 security group bị mở 0.0.0.0/0 ngoài ý muốn trong tương lai (thay vì phải chờ đến lần audit sau mới biết)?", "type": "choice", "choices": ["AWS Config rule theo dõi cấu hình liên tục", "Chỉ kiểm tra thủ công mỗi 6 tháng", "Không cần vì đã fix 1 lần rồi", "Đổi Security Group sang dùng Network ACL"], "answer": 0, "explanation": "AWS Config có thể gắn 1 ''rule'' tự động kiểm tra cấu hình mỗi thay đổi và báo ngay khi có security group mở 0.0.0.0/0 - đây là ''continuous monitoring'' mà cả PCI-DSS và SOC 2 đều kỳ vọng, thay vì kiểm tra thủ công định kỳ."}], "reference": "## Rà soát kiến trúc AWS theo PCI-DSS & SOC 2\n\n**4 vấn đề kinh điển hay gặp và cách fix, theo thứ tự nên làm:**\n1. **Hệ thống xử lý dữ liệu thẻ nằm ở public subnet không cần thiết** -> chuyển vào private subnet, chỉ expose qua ALB/API Gateway - giảm trực tiếp phạm vi CDE (Cardholder Data Environment) phải audit.\n2. **Chưa có CloudTrail** -> `create-trail` + `start-logging` - bằng chứng audit trail cơ bản nhất mà auditor luôn hỏi đầu tiên.\n3. **IAM role quá rộng (AdministratorAccess) trên 1 service cụ thể** -> vi phạm least privilege - thu nhỏ lại chỉ còn đúng quyền service đó cần.\n4. **Dữ liệu nhạy cảm chưa mã hóa at-rest** -> `put-bucket-encryption` với SSE-KMS làm default cho cả bucket, không phụ thuộc người upload có nhớ chỉ định hay không.\n5. **Không có continuous monitoring** -> AWS Config rule + GuardDuty, để PHÁT HIỆN drift (vd security group bị mở lại) ngay lập tức thay vì chờ audit định kỳ mới biết."}'::jsonb)
) AS v(pattern, target_front, payload)
JOIN decks d ON d.slug = 'labs' AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'aws')
ON CONFLICT (deck_id, kind, lower(front)) DO NOTHING;
